BEGIN;
SELECT quantity FROM inventory WHERE sku = :sku FOR UPDATE;
UPDATE inventory SET quantity = quantity - :requested WHERE sku = :sku;
INSERT INTO reservations(sku, quantity) VALUES (:sku, :requested);
COMMIT;

